{
  "development": {
    "responsibilities": [
      "Design and build applications that use LLMs (application-focused LLM Ops)",
      "Integrate the LLM at the center of the application architecture",
      "Create and iterate on prompts and application logic to elicit desired LLM behavior"
    ],
    "notes": "In LLM Ops you typically work around an existing model rather than training one from scratch."
  },
  "deployment": {
    "responsibilities": [
      "Deploy LLM-powered applications to production environments (not local systems)",
      "Ensure the LLM endpoints/services are correctly hosted and accessible by the application",
      "Validate behavior after deployment to confirm production readiness"
    ],
    "notes": "Deployment specifically targets production operation of LLMs and their integration with application stacks."
  },
  "management": {
    "responsibilities": [
      "Manage fine-tuning of models when needed",
      "Lead prompt engineering and iterative prompt improvement",
      "Conduct LLM evaluation (both application-specific evaluations and model-specific benchmarks)",
      "Enforce AI governance policies"
    ],
    "notes": "Management covers ongoing model tuning, evaluation, and governance once the system is in use."
  },
  "production": {
    "responsibilities": [
      "Operate and monitor LLMs running in production environments",
      "Address how LLMs behave and perform under real-world usage",
      "Run evaluations and benchmarks relevant to production needs"
    ],
    "notes": "Production responsibilities emphasize observing and managing LLM behavior in live systems, acknowledging LLMs' probabilistic (non-deterministic) nature."
  }
}

